package com.franco.desco.domain.salesoperation;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class SalesOperationModels{private SalesOperationModels(){}public record Summary(Long operativoVentaId,Long campaniaVentaId,String campania,String codigo,Instant fechaInicioProgramada,Instant fechaFinProgramada,Instant fechaInicioReal,Instant fechaFinReal,Integer cantidadJabasRecibidas,Long jabasAsignadas,Long jabasDevueltas,Long jabasDisponibles,Long jabasPendientes,BigDecimal kilosRecibidos,BigDecimal kilosAceptados,BigDecimal kilosRechazados,String estadoProceso,String observacion,Long participantes,Long entregas,Long incidenciasPendientes){}public record Header(Long operativoVentaId,String codigo,Long campaniaVentaId,String campania,Instant fechaInicioProgramada,Instant fechaFinProgramada,Instant fechaInicioReal,Instant fechaFinReal,String estadoProceso,String observacion,Integer jabasRecibidas,Integer jabasAsignadas,Integer jabasDevueltas,Integer jabasPendientes,Integer jabasDisponibles){}public record Zone(Long zonaProductivaId,String codigo,String nombre){}public record Participant(Long operativoSocioId,String estadoParticipacion,Long participacionId,String numeroDocumento,String socioNombre){}public record Delivery(Long entregaSocioId,String codigoLote,Instant fechaHora,BigDecimal pesoAceptadoKg,String estadoControlCalidad,String estadoProceso){}public record Incident(Long incidenciaId,String tipoIncidencia,String severidad,String descripcion,String estadoIncidencia){}public record Detail(Header operativo,List<Zone>zonas,List<Participant>participantes,List<Delivery>entregas,List<Incident>incidencias){public Detail{zonas=zonas==null?List.of():List.copyOf(zonas);participantes=participantes==null?List.of():List.copyOf(participantes);entregas=entregas==null?List.of():List.copyOf(entregas);incidencias=incidencias==null?List.of():List.copyOf(incidencias);}}}
